// /app/app/decimator.js — purchase helpers plus the live Decimator entry path.
//
// Ticket purchases still share DegenerusGame.purchase() with lootboxes, so
// those helpers remain direct re-exports. A Decimator entry is different: the
// player burns FLIP.decimatorBurn(player, amount, chips) during the open window.
// Since audit 92a1358d0 the Decimator is a shared-dice craps battle: a wallet has
// ONE accumulated entry per event, each burn adds to its stack and resets its
// board, and the board is the one the player keeps in the main Craps widget.

import { sendTx, getProvider, ethers } from './contracts.js';
import { requireStaticCall } from './static-call.js';
import { decodeRevertReason } from './reason-map.js';
import { CHAIN, CONTRACTS } from './chain-config.js';
import {
  permissionlessReadProvider,
  readContractStorage,
  readProviderBlockNumber,
} from './read-provider.js';
import { get, getActingAddress } from './store.js';
import { loadSchema } from '../chain/schema.js';

export { purchaseEth, scaledTicketPriceWei } from './lootbox.js';

const DECIMATOR_ABI = [
  'function decimatorBurn(address player, uint256 amount, uint32 chips) external',
  'event DecimatorBurn(address indexed player, uint256 amountBurned, uint64 entryId)',
  'error AmountLTMin()',
  'error NotDecimatorWindow()',
  'error NotApproved()',
  'error Insufficient()',
  'error E()',
];

const DECIMATOR_CONTEXT_ABI = [
  'function playerActivityScore(address player) external view returns (uint256 scorePoints)',
  'function futurePrizePoolView() external view returns (uint256)',
  'function currentDayView() external view returns (uint24)',
];

const DECIMATOR_STACK_EVENT_ABI = [
  'event DecBurnRecorded(address indexed player, uint24 indexed lvl, uint64 indexed entryId, uint256 baseAmount, uint256 credited, uint256 stack, uint32 chips)',
];
const DECIMATOR_BURN_EVENT_ABI = [
  'event DecimatorBurn(address indexed player, uint256 amountBurned, uint64 entryId)',
];

const BPS_DENOMINATOR = 10_000n;
const WAD = 10n ** 18n;
const DECIMATOR_NORMAL_POOL_BPS = 1_000n;
const DECIMATOR_CENTURY_POOL_BPS = 3_000n;
const DECIMATOR_LOG_CHUNK_BLOCKS = 1_800;
const DECIMATOR_BOON_CAP = 50_000n * 10n ** 18n;
// DegenerusGameDecimatorModule (audit 32c604531): an entry, keyed (lvl << 64) | id, is
// owner[0..159] | chips[160..189] | stack in whole FLIP[190..]; the wallet's decBattlePlayers slot
// holds its latest entry as lvl[64..87] | id[0..63].
const ENTRY_CHIPS_SHIFT = 160n;
const ENTRY_STACK_SHIFT = 190n;
const MASK_64 = (1n << 64n) - 1n;
const MASK_160 = (1n << 160n) - 1n;
const CHIPS_MASK = 0x3FFFFFFFn;

/** FLIP.sol DECIMATOR_MIN — FLIP is an unscaled 18-decimal token. */
export const DECIMATOR_MIN_FLIP_WEI = 1_000n * 10n ** 18n;

/**
 * Whether the normal Decimator burn window is live.
 *
 * The indexed flags are preferred. The level rule is a safe positive fallback
 * while the API crosses the x4/x99 transition; every write still performs the
 * contract static call before sending.
 */
export function decimatorWindowIsOpen(gameState, position = null) {
  if (gameState?.decWindowOpen === true
    || gameState?.decimator?.windowOpen === true
    || position?.windowOpen === true
    || String(position?.roundStatus || '').toLowerCase() === 'open') {
    return true;
  }

  const level = Number(gameState?.level);
  if (!Number.isInteger(level) || level < 0) return false;
  return (level % 10 === 4 && level % 100 !== 94) || level % 100 === 99;
}

let _contractFactory = null;
let _contextReaderForTest = null;
let _readProvider = null;
const _roundStackCache = new Map();
const _roundRawBurnCache = new Map();
const _roundStartBlockCache = new Map();

/** Test-only contract-construction seam. */
export function __setContractFactoryForTest(factory) {
  _contractFactory = typeof factory === 'function' ? factory : null;
}

/** Test-only live-context seam (score + timing flags). */
export function __setDecimatorContextReaderForTest(reader) {
  _contextReaderForTest = typeof reader === 'function' ? reader : null;
}

/** Test-only reset. */
export function __resetContractFactoryForTest() {
  _contractFactory = null;
  _contextReaderForTest = null;
  _readProvider = null;
  _roundStackCache.clear();
  _roundRawBurnCache.clear();
  _roundStartBlockCache.clear();
}

function _buildContract(signerOrProvider) {
  if (_contractFactory) return _contractFactory(signerOrProvider);
  return new ethers.Contract(CONTRACTS.COIN, DECIMATOR_ABI, signerOrProvider);
}

function _contextProvider() {
  return permissionlessReadProvider(getProvider());
}

function _activityScoreNumber(value) {
  if (value == null) return null;
  try {
    const parsed = BigInt(value);
    if (parsed >= 0n && parsed <= BigInt(Number.MAX_SAFE_INTEGER)) return Number(parsed);
  } catch (_e) { /* malformed reads remain unknown */ }
  return null;
}

/** Read only the live GAME score used by player-facing Degen Rating gates. */
export async function readPlayerActivityScore(player) {
  if (!player) return null;
  if (_contextReaderForTest) {
    try {
      const context = await _contextReaderForTest(player, null, { scoreOnly: true });
      return _activityScoreNumber(context?.activityScore);
    } catch (_e) {
      return null;
    }
  }

  try {
    const provider = _contextProvider();
    const game = new ethers.Contract(CONTRACTS.GAME, DECIMATOR_CONTEXT_ABI, provider);
    return _activityScoreNumber(await game.playerActivityScore(player));
  } catch (_e) {
    return null;
  }
}

async function _storageAt(provider, slot, blockTag = 'latest') {
  return readContractStorage(CONTRACTS.GAME, slot, { provider, blockTag });
}

function _mappingSlot(key, root, keyType = 'uint256') {
  return ethers.keccak256(ethers.AbiCoder.defaultAbiCoder().encode([keyType, 'uint256'], [key, BigInt(root)]));
}

async function _gameSlots() {
  const { fields } = await loadSchema('game');
  return {
    entries: BigInt(fields.decBattleEntries.slot),
    rounds: BigInt(fields.decBattleRounds.slot),
    players: BigInt(fields.decBattlePlayers.slot),
  };
}

/** Storage slot of decBattlePlayers[player]: the wallet's latest (lvl << 64) | id. */
export function decimatorPlayerStorageSlot(player, root) {
  try { return _mappingSlot(player, root, 'address'); }
  catch (_e) { return null; }
}

/** Storage slot of decBattleEntries[(level << 64) | entryId]. */
export function decimatorEntryStorageSlot(level, entryId, root) {
  try { return _mappingSlot((BigInt(level) << 64n) | BigInt(entryId), root); }
  catch (_e) { return null; }
}

/** Storage slot of decBattleRounds[level] (the struct's first word). */
export function decimatorRoundStorageSlot(level, root) {
  try { return _mappingSlot(BigInt(level), root); }
  catch (_e) { return null; }
}

/**
 * A wallet's entry for `level`: its latest-entry slot names the id, and only when that slot is
 * on this level does the wallet hold an entry here (no entry reads as id 0, stack 0).
 */
async function _readDecimatorEntry(provider, level, player, { players, entries }, tag) {
  const latest = decimatorPlayerSlotDecode(await _storageAt(provider, decimatorPlayerStorageSlot(player, players), tag));
  if (latest.entryId === 0n || latest.level !== level) return { entryId: 0n, chips: 0, stackWei: 0n };
  const entry = decimatorEntryDecode(await _storageAt(provider, decimatorEntryStorageSlot(level, latest.entryId, entries), tag));
  return { entryId: latest.entryId, chips: entry.chips, stackWei: entry.stackWei };
}

/** A wallet's decBattlePlayers word: the level and id of its latest entry (id 0 = none). */
export function decimatorPlayerSlotDecode(storageWord) {
  let word;
  try { word = BigInt(storageWord ?? 0); } catch (_e) { word = 0n; }
  return { level: Number((word >> 64n) & 0xFFFFFFn), entryId: word & MASK_64 };
}

/** One accumulated entry: its owner, its board and its credited stack (whole FLIP, in wei). */
export function decimatorEntryDecode(storageWord) {
  let word;
  try { word = BigInt(storageWord ?? 0); } catch (_e) { word = 0n; }
  return {
    owner: word & MASK_160,
    chips: Number((word >> ENTRY_CHIPS_SHIFT) & CHIPS_MASK),
    stackWei: (word >> ENTRY_STACK_SHIFT) * WAD,
  };
}

/** DecBattleRound word 0: poolWei | count | openedDay | phase | capacity | winners | paid. */
export function decimatorRoundDecode(storageWord) {
  let word;
  try { word = BigInt(storageWord ?? 0); } catch (_e) { word = 0n; }
  return {
    poolWei: word & ((1n << 128n) - 1n),
    entrants: Number((word >> 128n) & MASK_64),
    openedDay: Number((word >> 192n) & 0xFFFFFFn),
    phase: Number((word >> 216n) & 0xFFn),
    capacity: Number((word >> 224n) & 0xFFn),
    winners: Number((word >> 232n) & 0xFFn),
    paid: Number((word >> 240n) & 0xFFn),
  };
}

/**
 * Exact ActivityCurveLib.decBattleMultBps port (whole-point activity score in,
 * basis points out): the early knee, 1.9x at 500, then 2x at 30,000. Integer
 * division mirrors Solidity.
 */
export function decimatorActivityMultiplierBps(score) {
  let points;
  try { points = BigInt(score ?? 0); } catch (_e) { points = 0n; }
  if (points <= 0n) return 10_000n;
  if (points <= 235n) return 10_000n + (points * 7_049n) / 235n;
  if (points <= 500n) return 17_049n + ((points - 235n) * 1_951n) / 265n;
  if (points >= 30_000n) return 20_000n;
  return 19_000n + ((points - 500n) * 1_000n) / 29_500n;
}

/** Exact DecimatorModule._dayFactor: 0.9^daysLate in 18 decimals, floored at each squaring. */
export function decimatorDayFactorWei(daysLate) {
  let late;
  try { late = BigInt(daysLate ?? 0); } catch (_e) { late = 0n; }
  if (late < 0n) late = 0n;
  let factor = WAD;
  let base = 9n * 10n ** 17n;
  while (late !== 0n) {
    if ((late & 1n) !== 0n) factor = (factor * base) / WAD;
    late >>= 1n;
    if (late !== 0n) base = (base * base) / WAD;
  }
  return factor;
}

/** Activity times entry timing, in basis points: the rate one FLIP of base amount buys stack. */
export function decimatorCurrentMultiplierBps({ activityScore = 0, daysLate = 0 } = {}) {
  return (decimatorActivityMultiplierBps(activityScore) * decimatorDayFactorWei(daysLate)) / WAD;
}

/**
 * Exact stack a burn credits (DecimatorModule.recordDecBurn): the base amount, plus the boon's
 * boost on at most 50k FLIP, times the degen multiplier and 0.9 per day since the window
 * opened, rounded down to whole FLIP. The quest-completion credit is left out: it is only known
 * once the burn lands.
 */
export function decimatorStackCreditWei({
  amountWei = 0n,
  activityScore = 0,
  daysLate = 0,
  boonBps = 0,
} = {}) {
  let amount;
  let boon;
  try {
    amount = BigInt(amountWei);
    boon = BigInt(boonBps);
  } catch (_e) {
    return 0n;
  }
  if (amount <= 0n) return 0n;
  if (boon < 0n) boon = 0n;
  const boonBase = amount > DECIMATOR_BOON_CAP ? DECIMATOR_BOON_CAP : amount;
  const baseAmount = amount + (boonBase * boon) / BPS_DENOMINATOR;
  const rate = decimatorDayFactorWei(daysLate) * decimatorActivityMultiplierBps(activityScore);
  return ((baseAmount * rate) / (WAD * BPS_DENOMINATOR * WAD)) * WAD;
}

/** Effective stack per FLIP for this burn, boon included, in basis points. */
export function decimatorEffectiveMultiplierBps(args = {}) {
  let amount;
  try { amount = BigInt(args?.amountWei ?? 0); } catch (_e) { return null; }
  if (amount <= 0n) return null;
  return (decimatorStackCreditWei(args) * BPS_DENOMINATOR) / amount;
}

const DECIMATOR_BOARD_LEGS = Object.freeze([
  'PASS', '4', '5', '6', '8', '9', '10', 'HARD 4', 'HARD 8', "DON'T PASS",
]);

/** A normal battle's board rules, as DecimatorModule._checkBoard enforces them. */
export function decimatorBoardValid(chips) {
  const packed = Number(chips) >>> 0;
  if (packed > 0x3FFFFFFF) return false;
  if ((packed & 7) !== 0 && (packed >>> 27) !== 0) return false;
  if (((packed >>> 2) & 0x9249249) !== 0) return false;
  return decimatorBoardSummary(packed).named <= 7;
}

/** How many chips a board names, and where (the dice place the rest of the ten). */
export function decimatorBoardSummary(chips) {
  const packed = Number(chips) >>> 0;
  const legs = [];
  let named = 0;
  DECIMATOR_BOARD_LEGS.forEach((label, index) => {
    const count = (packed >>> (3 * index)) & 7;
    if (count > 0) legs.push({ label, count });
    named += count;
  });
  return { named, random: Math.max(0, 10 - named), legs };
}

/**
 * The board a Decimator burn sends: the one the main Craps widget shows for this player, which
 * loads their saved board (CrapsBattle.preferredBoardOf) and follows their edits. Before that
 * widget has loaded, read the saved board directly. Zero lets the dice place all ten.
 */
export async function readDecimatorBoardChips(player) {
  const published = get('ui.crapsBoard');
  if (published && player && String(published.player || '') === String(player).toLowerCase()) {
    return Number(published.chips ?? 0) >>> 0;
  }
  if (!player) return 0;
  try {
    const { readCrapsPassCredits } = await import('./craps.js');
    return Number((await readCrapsPassCredits(player))?.preferredBoard?.chips ?? 0) >>> 0;
  } catch (_e) {
    return 0;
  }
}

/** The open x00 Decimator is 30%; every ordinary x5 Decimator is 10%. */
export function decimatorPoolBps(level) {
  const lvl = Number(level);
  return Number.isInteger(lvl) && lvl > 0 && lvl % 100 === 0
    ? DECIMATOR_CENTURY_POOL_BPS
    : DECIMATOR_NORMAL_POOL_BPS;
}

export function decimatorPoolWei(futurePoolWei, level) {
  let future;
  try { future = BigInt(futurePoolWei ?? 0); } catch (_e) { return 0n; }
  if (future <= 0n) return 0n;
  return (future * decimatorPoolBps(level)) / BPS_DENOMINATOR;
}

function _decimatorStackInterface() {
  return new ethers.Interface(DECIMATOR_STACK_EVENT_ABI);
}

function _applyDecimatorStackLogs(players, logs) {
  const iface = _decimatorStackInterface();
  const ordered = Array.from(logs || []).sort((a, b) => (
    Number(a?.blockNumber || 0) - Number(b?.blockNumber || 0)
    || Number(a?.index ?? a?.logIndex ?? 0) - Number(b?.index ?? b?.logIndex ?? 0)
  ));
  for (const log of ordered) {
    try {
      const args = iface.parseLog(log)?.args;
      const player = String(args?.player || '').toLowerCase();
      if (player) players.set(player, BigInt(args?.stack ?? 0));
    } catch (_e) { /* an unrelated or malformed log contributes nothing */ }
  }
}

/**
 * Sum every entry's latest stack for one open Decimator event. DecBurnRecorded
 * is emitted by GAME and indexed by level; its `stack` is the entry's running
 * total. The 1,800-block chunks stay below Base's public 2,000-block
 * eth_getLogs limit; subsequent hot polls read only new blocks.
 */
async function _readDecimatorRoundStack(provider, level) {
  const lvl = Number(level);
  if (!Number.isInteger(lvl) || lvl < 1 || typeof provider?.getLogs !== 'function') return null;
  const cached = _roundStackCache.get(lvl);
  const state = cached?.provider === provider
    ? cached
    : {
        provider,
        players: new Map(),
        nextBlock: Math.max(0, Number(CHAIN.deployBlock) || 0),
        total: 0n,
        pending: null,
      };
  if (!cached || cached.provider !== provider) _roundStackCache.set(lvl, state);
  if (state.pending) return state.pending;

  state.pending = (async () => {
    const head = Number(await readProviderBlockNumber(provider, { maxAgeMs: 0 }));
    if (!Number.isInteger(head) || head < 0) return state.total;
    if (head < state.nextBlock) {
      state.players.clear();
      state.nextBlock = Math.max(0, Number(CHAIN.deployBlock) || 0);
    }

    const iface = _decimatorStackInterface();
    const event = iface.getEvent('DecBurnRecorded');
    const filter = {
      address: CONTRACTS.GAME,
      topics: [
        event.topicHash,
        null,
        ethers.zeroPadValue(ethers.toBeHex(lvl), 32),
      ],
    };
    for (let from = state.nextBlock; from <= head; from += DECIMATOR_LOG_CHUNK_BLOCKS) {
      const to = Math.min(head, from + DECIMATOR_LOG_CHUNK_BLOCKS - 1);
      const logs = await provider.getLogs({ ...filter, fromBlock: from, toBlock: to });
      _applyDecimatorStackLogs(state.players, logs);
    }
    state.nextBlock = head + 1;
    state.total = Array.from(state.players.values()).reduce((sum, value) => sum + value, 0n);
    return state.total;
  })();

  try {
    return await state.pending;
  } finally {
    state.pending = null;
  }
}

async function _readIndexedDecimatorRoundStack(level) {
  const lvl = Number(level);
  if (!Number.isInteger(lvl) || lvl < 1) return null;
  try {
    // Keep the beta API module lazy here. It installs browser listeners at
    // module evaluation time, while this helper is also imported by the
    // side-effect-free Node unit tests.
    const { fetchJSON } = await import('./api.js');
    const payload = await fetchJSON(`/game/decimator/${lvl}`);
    if (payload?.totalStack == null) return null;
    const total = BigInt(payload.totalStack);
    return total >= 0n ? total : null;
  } catch (_e) {
    // Rolling deploy compatibility: older API workers do not have this route.
    return null;
  }
}

async function _readFastDecimatorRoundStack(provider, level) {
  const indexed = await _readIndexedDecimatorRoundStack(level);
  return indexed == null ? _readDecimatorRoundStack(provider, level) : indexed;
}

function _unixSeconds(value) {
  const parsed = Number(value);
  if (!Number.isFinite(parsed) || parsed <= 0) return null;
  return Math.trunc(parsed > 10_000_000_000 ? parsed / 1_000 : parsed);
}

async function _firstBlockAtOrAfter(provider, timestamp, head) {
  let low = Math.max(0, Number(CHAIN.deployBlock) || 0);
  let high = Math.max(low, Number(head) || low);
  while (low < high) {
    const mid = low + Math.floor((high - low) / 2);
    const block = await provider.getBlock(mid);
    const blockTime = Number(block?.timestamp || 0);
    if (blockTime >= timestamp) high = mid;
    else low = mid + 1;
  }
  return low;
}

/** Indexed stage-7 block that opens the burn window for target level N+1. */
export async function readIndexedDecimatorWindowStartBlock(targetLevel) {
  const target = Number(targetLevel);
  const windowLevel = target - 1;
  if (!Number.isInteger(windowLevel) || windowLevel < 0) return null;
  if (_roundStartBlockCache.has(target)) return _roundStartBlockCache.get(target);
  try {
    const { fetchJSON } = await import('./api.js');
    if (CHAIN.readMode === 'chain') {
      const payload = await fetchJSON(`/history/levels?level=${windowLevel}`);
      const opening = payload.items.filter(row => row.stage === 7).at(-1)?.blockNumber ?? null;
      if (opening != null) _roundStartBlockCache.set(target, opening);
      return opening;
    }
    let cursor = null;
    // The history feed is ascending and capped at 100 rows. A Decimator only
    // opens once per ten levels, so this cold lookup is rare and its answer is
    // cached for the browser session.
    for (let page = 0; page < 200; page += 1) {
      const suffix = cursor
        ? `?limit=100&cursor=${encodeURIComponent(cursor)}`
        : '?limit=100';
      const payload = await fetchJSON(`/history/levels${suffix}`);
      const rows = Array.isArray(payload?.items) ? payload.items : [];
      const opening = rows
        .filter((row) => Number(row?.level) === windowLevel && Number(row?.stage) === 7)
        .map((row) => Number(row?.blockNumber))
        .filter((block) => Number.isInteger(block) && block >= 0)
        .sort((a, b) => b - a)[0];
      if (opening != null) {
        _roundStartBlockCache.set(target, opening);
        return opening;
      }
      // Once an ascending page has moved beyond this level, a missing stage-7
      // row is genuinely not indexed yet. Let the next widget poll retry.
      if (rows.some((row) => Number(row?.level) > windowLevel)) return null;
      cursor = payload?.nextCursor ? String(payload.nextCursor) : null;
      if (!cursor) return null;
    }
  } catch (_e) { /* rolling API / local indexer may not expose history yet */ }
  return null;
}

/** Sum the unweighted FLIP actually destroyed in the current level's window. */
export async function readDecimatorRawBurnTotal({ level, sinceTimestamp, sinceBlock } = {}) {
  const lvl = Number(level);
  const startTime = _unixSeconds(sinceTimestamp);
  let startBlock = Number(sinceBlock);
  if (!Number.isInteger(startBlock) || startBlock < 0) startBlock = null;
  if (!Number.isInteger(lvl) || lvl < 1) return null;
  if (startTime == null && startBlock == null) {
    startBlock = await readIndexedDecimatorWindowStartBlock(lvl);
  }
  if (startTime == null && startBlock == null) return null;
  const provider = _contextProvider();
  if (typeof provider?.getLogs !== 'function'
    || typeof provider?.getBlock !== 'function'
    || typeof provider?.getBlockNumber !== 'function') return null;

  const boundaryKey = startBlock == null ? `t${startTime}` : `b${startBlock}`;
  const cacheKey = `${Number(CHAIN.id)}:${lvl}:${boundaryKey}`;
  const cached = _roundRawBurnCache.get(cacheKey);
  const state = cached?.provider === provider
    ? cached
    : { provider, nextBlock: null, total: 0n, pending: null };
  if (!cached || cached.provider !== provider) _roundRawBurnCache.set(cacheKey, state);
  if (state.pending) return state.pending;

  state.pending = (async () => {
    const head = Number(await readProviderBlockNumber(provider, { maxAgeMs: 0 }));
    if (!Number.isInteger(head) || head < 0) return state.total;
    if (state.nextBlock == null) {
      state.nextBlock = startBlock == null
        ? await _firstBlockAtOrAfter(provider, startTime, head)
        : startBlock;
    }
    if (head < state.nextBlock) return state.total;

    const iface = new ethers.Interface(DECIMATOR_BURN_EVENT_ABI);
    const event = iface.getEvent('DecimatorBurn');
    for (let from = state.nextBlock; from <= head; from += DECIMATOR_LOG_CHUNK_BLOCKS) {
      const to = Math.min(head, from + DECIMATOR_LOG_CHUNK_BLOCKS - 1);
      const logs = await provider.getLogs({
        address: CONTRACTS.COIN,
        topics: [event.topicHash],
        fromBlock: from,
        toBlock: to,
      });
      for (const log of logs || []) {
        try { state.total += BigInt(iface.parseLog(log)?.args?.amountBurned ?? 0); }
        catch (_e) { /* unrelated/malformed log */ }
      }
      // Advance after each successful chunk so a later RPC-range failure can
      // resume without counting the completed chunks twice.
      state.nextBlock = to + 1;
    }
    return state.total;
  })();

  try {
    return await state.pending;
  } finally {
    state.pending = null;
  }
}

/**
 * Read what a burn is quoted against right now: the activity score, how many
 * days late the entry is (0.9 a day since the window opened), the player's
 * current entry (stack and board) and the event's running totals. Each leg
 * soft-fails independently so a provider without raw-storage support can still
 * show the multiplier.
 */
export async function readDecimatorContext(player, targetLevel = null, options = {}) {
  if (_contextReaderForTest) return _contextReaderForTest(player, targetLevel, options);

  const provider = _contextProvider();
  const game = new ethers.Contract(CONTRACTS.GAME, DECIMATOR_CONTEXT_ABI, provider);
  let blockTag = null;
  try { blockTag = await readProviderBlockNumber(provider); }
  catch (_e) { /* latest reads remain a useful soft-failure fallback */ }
  const overrides = blockTag == null ? [] : [{ blockTag }];
  const tag = blockTag ?? 'latest';
  const lvl = Number(targetLevel);
  const levelKnown = Number.isInteger(lvl) && lvl >= 1 && lvl <= 0xFFFFFF;
  const slots = levelKnown ? _gameSlots() : Promise.reject(new Error('no level'));
  const [
    scoreRead,
    dayRead,
    futureRead,
    roundRead,
    entryRead,
    roundStackRead,
    rawBurnRead,
  ] = await Promise.allSettled([
    player ? game.playerActivityScore(player, ...overrides) : Promise.resolve(null),
    game.currentDayView(...overrides),
    game.futurePrizePoolView(...overrides),
    slots.then(({ rounds }) => _storageAt(provider, decimatorRoundStorageSlot(lvl, rounds), tag)),
    player ? slots.then((roots) => _readDecimatorEntry(provider, lvl, player, roots, tag)) : Promise.resolve(null),
    _readFastDecimatorRoundStack(provider, targetLevel),
    options?.sinceTimestamp == null
      ? Promise.resolve(null)
      : readDecimatorRawBurnTotal({ level: targetLevel, sinceTimestamp: options.sinceTimestamp }),
  ]);

  const activityScore = scoreRead.status === 'fulfilled'
    ? _activityScoreNumber(scoreRead.value)
    : null;

  let futurePoolWei = null;
  if (futureRead.status === 'fulfilled') {
    try { futurePoolWei = BigInt(futureRead.value); } catch (_e) { /* unknown */ }
  }

  let round = null;
  if (roundRead.status === 'fulfilled' && roundRead.value != null) round = decimatorRoundDecode(roundRead.value);

  // recordDecBurn times the entry from the round's openedDay (set when the window arms).
  let daysLate = null;
  if (dayRead.status === 'fulfilled' && round && round.openedDay > 0) {
    const today = Number(dayRead.value);
    if (Number.isInteger(today) && today >= round.openedDay) daysLate = today - round.openedDay;
  }

  const entry = entryRead.status === 'fulfilled' ? entryRead.value : null;

  let totalStackWei = null;
  if (roundStackRead.status === 'fulfilled' && roundStackRead.value != null) {
    try { totalStackWei = BigInt(roundStackRead.value); } catch (_e) { /* unknown */ }
  }

  let totalRawBurnWei = null;
  if (rawBurnRead.status === 'fulfilled' && rawBurnRead.value != null) {
    try { totalRawBurnWei = BigInt(rawBurnRead.value); } catch (_e) { /* unknown */ }
  }

  return {
    activityScore,
    daysLate,
    futurePoolWei,
    entrants: round ? round.entrants : null,
    entryId: entry && entry.entryId !== 0n ? entry.entryId : null,
    stackWei: entry ? entry.stackWei : null,
    entryChips: entry && entry.entryId !== 0n ? entry.chips : null,
    totalStackWei,
    totalRawBurnWei,
  };
}

function _decimatorError(error, context) {
  // AmountLTMin is shared with the 100-FLIP coinflip minimum, so registering a
  // global message here would make whichever module imported last lie. Keep
  // the shared selector's Decimator-specific copy local to this write path.
  const name = error?.revert?.name || error?.errorName || null;
  const local = {
    AmountLTMin: {
      code: 'AmountLTMin',
      userMessage: 'Minimum Decimator entry is 1,000 FLIP.',
      recoveryAction: 'Enter at least 1,000 FLIP.',
    },
    NotDecimatorWindow: {
      code: 'NotDecimatorWindow',
      userMessage: 'The Decimator entry window is closed.',
      recoveryAction: 'Wait for the next Decimator window.',
    },
    Insufficient: {
      code: 'Insufficient',
      userMessage: 'Not enough wallet or claimable FLIP for that Decimator entry.',
      recoveryAction: 'Lower the entry size or add more FLIP.',
    },
    // DecimatorModule.recordDecBurn's single revert: a bad board, or an event that is not
    // taking entries (closed, sealed or over).
    E: {
      code: 'DecimatorEntryRejected',
      userMessage: 'The Decimator did not accept that entry.',
      recoveryAction: 'Check your Craps board (at most seven chips, three a spot, not both pass lines) and that the window is open.',
    },
  }[name];
  const decoded = local || decodeRevertReason(error);
  const wrapped = new Error(decoded.userMessage || `Failed: ${context}`);
  wrapped.code = decoded.code;
  wrapped.userMessage = decoded.userMessage;
  wrapped.recoveryAction = decoded.recoveryAction;
  wrapped.cause = error;
  return wrapped;
}

/**
 * Burn FLIP into the currently open Decimator round.
 *
 * FLIP.decimatorBurn consumes liquid FLIP first and can consume the player's
 * coinflip claimable shortfall on-chain, so the UI does not need a claim-first
 * transaction here.
 *
 * The burn also sets the entry's board. Unless `chips` is given, it sends the
 * board the player keeps in the main Craps widget (readDecimatorBoardChips).
 *
 * @param {{amount: bigint|string|number, player?: string, chips?: number}} args
 * @returns {Promise<{receipt: import('ethers').TransactionReceipt, amount: bigint, chips: number}>}
 */
export async function burnForDecimator({ amount, player, chips } = {}) {
  const target = player || getActingAddress();
  if (!target) throw new Error('Connect a wallet first.');

  let amountWei;
  try {
    amountWei = BigInt(amount);
  } catch (_e) {
    throw new Error('Decimator size must be a numeric FLIP amount.');
  }
  if (amountWei < DECIMATOR_MIN_FLIP_WEI) {
    throw new Error('Minimum Decimator entry is 1,000 FLIP.');
  }
  const board = chips == null ? await readDecimatorBoardChips(target) : Number(chips) >>> 0;
  if (!decimatorBoardValid(board)) throw new Error('That Craps board is not a valid Decimator board.');

  const provider = getProvider();
  const signer = provider ? await provider.getSigner() : null;
  if (signer) {
    const sim = await requireStaticCall(
      _buildContract(signer),
      'decimatorBurn',
      [target, amountWei, board],
      signer,
    );
    if (!sim.ok) throw _decimatorError(sim.error, 'static-call decimatorBurn');
  }

  try {
    const receipt = await sendTx(
      (freshSigner) => _buildContract(freshSigner).decimatorBurn(target, amountWei, board),
      'Enter Decimator',
    );
    return { receipt, amount: amountWei, chips: board };
  } catch (error) {
    // Preserve wallet/network errors. Contract errors carry a parsed custom
    // error name because the ABI above includes every Decimator failure.
    if (error?.revert?.name || error?.errorName) {
      throw _decimatorError(error, 'decimatorBurn');
    }
    throw error;
  }
}
